    @Override public void onDestroy(){super.onDestroy();images.clear();worker.shutdownNow();}
    private void saveDraft(){if(screen.equals("edit"))captureEditor();if(draft==null)return;android.util.AtomicFile file=new android.util.AtomicFile(new File(getFilesDir(),"editor-draft.json"));FileOutputStream out=null;try{out=file.startWrite();out.write(draft.toString().getBytes("UTF-8"));file.finishWrite(out);}catch(Exception error){if(out!=null)file.failWrite(out);toast("No pudimos conservar el borrador. Intenta guardar antes de salir.");}}
    @Override public void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);saveDraft();out.putString("screen",screen);out.putString("id",currentId);out.putString("photoFor",photoFor);out.putInt("editorStep",editorStep);out.putBoolean("editorMore",editorMore);if(saleDraft!=null)out.putString("saleDraft",saleDraft.toString());}
    @Override public void onBackPressed(){
        if(screen.equals("home"))super.onBackPressed();
        else if(Arrays.asList("products","publications","orders").contains(screen))go("home","");
        else if(screen.equals("edit")&&editorStep>0){captureEditor();editorStep=0;render();}
        else if(screen.equals("edit")){captureEditor();saveDraft();go("products","");toast("Borrador conservado. Puedes continuarlo desde Inicio.");}
        else if(screen.equals("photo"))go("edit",currentId);
        else if(screen.equals("schedule"))go("home","");
        else if(screen.equals("orderSchedule"))go("order",currentId);
        else if(screen.equals("qr"))go("payments","");
        else if(Arrays.asList("profile","delivery","payments","connection","help").contains(screen))go("settings","");
        else if(screen.equals("order"))go("orders","");
        else if(screen.equals("publish")||screen.equals("promo"))go("publications","");
        else go("products","");
    }
