    private boolean enqueue(String type,JSONObject value,String destination){if(syncing){toast("Espera un momento mientras actualizamos.");return false;}try{store.enqueue(type,value);screen=destination;render();toast("Guardado en este celular. Pendiente de publicar.");sync(false);return true;}catch(Exception e){toast("No se pudo guardar. Conserva la pantalla y vuelve a intentar.");return false;}}
    private void sync(boolean notify){if(syncing)return;if(!notify&&!getPreferences(0).getBoolean("syncEnabled",false))return;if(serverUrl().isEmpty()||adminKey().isEmpty()){if(notify)go("connection","");return;}syncing=true;final String url=serverUrl(),key=adminKey();final int beforeRevision=data().optInt("revision"),beforePending=pending();final boolean wasOnline=online;worker.execute(()->{String problem="";try{JSONArray ops=store.snapshot().optJSONArray("pending");for(int i=0;ops!=null&&i<ops.length();i++){JSONObject op=ops.getJSONObject(i);store.markAttempted(op.optString("id"));JSONObject remote=request(url+"/api/admin/operations",key,op);store.accept(remote,op.optString("id"));}JSONObject remote=request(url+"/api/admin/state",key,null);store.accept(remote,"");online=true;}catch(Exception error){online=false;problem=error.getMessage()==null?"No pudimos conectar con la laptop.":error.getMessage();}final String message=problem;runOnUiThread(()->{syncing=false;syncError=message;if(isFinishing()||isDestroyed())return;JSONArray orders=data().optJSONArray("orders");int newOrders=0;for(int i=0;orders!=null&&i<orders.length();i++){JSONObject o=orders.optJSONObject(i);if(!knownOrders.contains(o.optString("id"))&&o.optString("status").equals("registered"))newOrders++;knownOrders.add(o.optString("id"));}if(ordersLoaded&&newOrders>0)toast(newOrders==1?"Llegó un nuevo pedido":"Llegaron "+newOrders+" pedidos");if(online)ordersLoaded=true;boolean changed=beforeRevision!=data().optInt("revision")||beforePending!=pending()||wasOnline!=online;if((changed||notify)&&Arrays.asList("home","products","orders","order").contains(screen)){int y=scroll.getScrollY();render();scroll.post(()->scroll.scrollTo(0,y));}if(notify)toast(message.isEmpty()?"Catálogo y pedidos actualizados.":message);});});}
    private JSONObject request(String url,String key,JSONObject body)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();try{c.setConnectTimeout(5000);c.setReadTimeout(8000);c.setRequestProperty("X-Manchapp-Key",key);if(body!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=utf-8");byte[] bytes=body.toString().getBytes("UTF-8");c.setFixedLengthStreamingMode(bytes.length);try(OutputStream out=c.getOutputStream()){out.write(bytes);}}int code=c.getResponseCode();JSONObject result=new JSONObject(LocalStore.read(code>=400?c.getErrorStream():c.getInputStream()));if(code>=400)throw new IOException(result.optString("error","No se pudo enviar el cambio."));return result;}catch(SocketTimeoutException|ConnectException|UnknownHostException e){throw new IOException("Sin conexión con la laptop. Tus cambios siguen guardados en este teléfono.");}finally{c.disconnect();}}
    private void showSyncProblem(){String message=syncError.isEmpty()?"Hay un cambio pendiente. Conecta para publicarlo antes de volver a editar.":syncError;new AlertDialog.Builder(this).setTitle("Cambios pendientes").setMessage(message).setNegativeButton("Cerrar",null).setNeutralButton("Conexión",(d,w)->go("connection","")).setPositiveButton("Revisar",(d,w)->reviewPending()).show();}
    private void reviewPending(){JSONArray ops=data().optJSONArray("pending");if(ops==null||ops.length()==0){sync(true);return;}JSONObject op=ops.optJSONObject(0),value=op.optJSONObject("data");String type=op.optString("type");if(!type.equals("product")&&!type.equals("order")){sync(true);return;}new AlertDialog.Builder(this).setTitle("Revisar cambio pendiente").setMessage("Podemos volver a cargar la información del catálogo. El cambio pendiente se conservará como borrador para que revises la cantidad antes de guardarlo otra vez.").setNegativeButton("Volver",null).setPositiveButton("Cargar y revisar",(d,w)->{if(syncing)return;syncing=true;worker.execute(()->{try{JSONObject remote=request(serverUrl()+"/api/admin/state",adminKey(),null);store.accept(remote,op.optString("id"));runOnUiThread(()->{syncing=false;syncError="";if(type.equals("product")){JSONObject fresh=find("products",value.optString("id"));draft=LocalStore.copy(value);if(fresh!=null){put(draft,"version",fresh.optInt("version"));put(draft,"stock",fresh.optInt("stock"));}pickedImage=draft.optString("image");go("edit",value.optString("id"));toast("Revisa la cantidad actual del catálogo antes de guardar.");}else go("order",value.optString("id"));});}catch(Exception e){runOnUiThread(()->{syncing=false;toast("No pudimos conectar. Tu cambio sigue guardado.");});}});}).show();}

    private void choosePhoto(String target,boolean camera){if(screen.equals("edit"))captureEditor();photoFor=target;try{if(camera){File dir=new File(getCacheDir(),"shared");dir.mkdirs();cameraUri=Uri.parse("content://pe.manchapp.beta.files/camera.jpg");Intent intent=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);intent.putExtra(MediaStore.EXTRA_OUTPUT,cameraUri);intent.addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_READ_URI_PERMISSION);intent.setClipData(ClipData.newRawUri("Foto",cameraUri));startActivityForResult(intent,41);}else{Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.setType("image/*");intent.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(intent,42);}}catch(Exception e){toast("No se pudo abrir la cámara o la galería de este equipo.");}}
    @Override protected void onActivityResult(int request,int result,Intent intent){super.onActivityResult(request,result,intent);if(request==84){if(result==RESULT_OK){try{String encoded=LocalStore.read(new FileInputStream(PhotoEditorActivity.output(this)));pickedImage=encoded;if(draft==null)draft=new JSONObject();put(draft,"image",encoded);put(draft,"imageReference",false);editorStep=1;screen="edit";saveDraft();render();toast("Foto aplicada. Guarda el producto para conservar el cambio.");}catch(Exception error){toast("No pudimos recuperar la foto editada. Tu producto se conserva.");}}return;}if(result!=RESULT_OK||!(request==41||request==42))return;Uri uri=request==41?Uri.parse("content://pe.manchapp.beta.files/camera.jpg"):intent==null?null:intent.getData();if(uri==null)return;final String target=photoFor;toast("Preparando imagen…");worker.execute(()->{try{Bitmap bitmap=ImageTools.read(this,uri);String encoded=target.equals("qr")?ImageTools.encodeQr(bitmap):ImageTools.encodeEdited(bitmap);bitmap.recycle();if(target.equals("qr"))rememberQr(encoded);runOnUiThread(()->{if(isFinishing()||isDestroyed())return;if(target.equals("qr")){pendingQr=encoded;go("qr","");}else{pickedImage=encoded;if(draft==null)draft=new JSONObject();put(draft,"image",encoded);put(draft,"imageReference",false);editorStep=1;screen="edit";render();toast("Foto lista. Guarda el producto para conservarla.");}});}catch(Exception|OutOfMemoryError error){runOnUiThread(()->toast(target.equals("qr")?"No pudimos preparar el QR. Elige una captura clara y de menor tamaño.":"No pudimos preparar esa imagen. Prueba una foto de menor tamaño."));}});}
    private void imageBank(){captureEditor();String[] names={"Papa rellena","Causa","Cachanga","Mazamorra","Café"},ids={"papa","causa","cachanga","mazamorra","cafe"};new AlertDialog.Builder(this).setTitle("Ilustraciones para tus productos").setItems(names,(d,index)->{pickedImage="";put(draft,"image","");put(draft,"illustration",ids[index]);put(draft,"imageReference",true);render();}).setNegativeButton("Volver",null).show();}
    private void improvePhoto(){captureEditor();saveDraft();final JSONObject source=LocalStore.copy(draft);if(!pickedImage.isEmpty())put(source,"image",pickedImage);toast("Abriendo editor de fotos…");worker.execute(()->{Bitmap original=null;try{original=ImageTools.productPhoto(this,source,960);if(original==null)throw new IOException();float scale=Math.min(1f,960f/Math.max(original.getWidth(),original.getHeight()));if(scale<1){Bitmap small=Bitmap.createScaledBitmap(original,Math.max(1,Math.round(original.getWidth()*scale)),Math.max(1,Math.round(original.getHeight()*scale)),true);if(small!=original)original.recycle();original=small;}try(OutputStream out=new FileOutputStream(PhotoEditorActivity.input(this))){if(!original.compress(ImageTools.hasTransparency(original)?Bitmap.CompressFormat.PNG:Bitmap.CompressFormat.JPEG,95,out))throw new IOException();}runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())startActivityForResult(new Intent(this,PhotoEditorActivity.class).putExtra("includeObjects",source.optString("category").equals("Combos")),84);});}catch(Exception|OutOfMemoryError error){runOnUiThread(()->toast("No pudimos abrir esa foto. Elige una imagen de menor tamaño."));}finally{if(original!=null&&!original.isRecycled())original.recycle();}});}

    private void showPhoto(){title("Una foto con más luz","Compara y elige la que mejor muestre tu plato.");if(improving){note("Ajustando la imagen en este teléfono…");return;}segmented(new String[]{"Original","Con más luz"},improvedSelected?1:0,i->{improvedSelected=i==1;render();});JSONObject p=new JSONObject();put(p,"image",improvedSelected&&!photoImproved.isEmpty()?photoImproved:photoOriginal);ImageView preview=image(p,480);preview.setScaleType(ImageView.ScaleType.FIT_CENTER);add(content,preview,20);preview.getLayoutParams().height=dp(350);note("Ajuste local de iluminación. Esta versión no utiliza un modelo de IA ni cambia el fondo.");primary("Usar esta foto",()->{pickedImage=improvedSelected&&!photoImproved.isEmpty()?photoImproved:photoOriginal;put(draft,"image",pickedImage);go("edit",currentId);});}
    private void createFlyer(JSONObject p,String message){JSONObject settings=data().optJSONObject("settings");int style=flyerStyle;toast("Preparando afiche…");worker.execute(()->{try{Bitmap bitmap=FlyerRenderer.render(p,settings,message,style,ui);File dir=new File(getCacheDir(),"shared");dir.mkdirs();File file=new File(dir,"manchapp-publicacion.png");try(OutputStream out=new FileOutputStream(file)){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();runOnUiThread(()->{try{Uri uri=Uri.parse("content://pe.manchapp.beta.files/"+file.getName());Intent share=new Intent(Intent.ACTION_SEND);share.setType("image/png");share.putExtra(Intent.EXTRA_STREAM,uri);String link=settings.optString("catalogUrl");share.putExtra(Intent.EXTRA_TEXT,message+"\n"+p.optString("name")+" · "+cash(p.optDouble("price"))+"\nVenta: "+SaleSchedule.day(settings)+"\n"+SaleSchedule.window(settings)+"\nReservas hasta "+SaleSchedule.deadline(settings)+"\n"+settings.optString("pickup")+(link.isEmpty()?"":"\nVer catálogo: "+link));share.setClipData(ClipData.newRawUri("Afiche",uri));share.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(share,"Compartir publicación"));}catch(Exception error){toast("No hay una aplicación disponible para compartir en este equipo.");}});}catch(Exception|OutOfMemoryError error){runOnUiThread(()->toast("No pudimos preparar el afiche. Prueba una foto más pequeña."));}});}
